{
  "feature_title": "User Authentication",
  "feature_description": "Allows registered users to securely log in to access their personalized dashboard",
  "scenarios": [
    {
      "tags": ["@smoke", "@authentication"],
      "type": "Scenario",
      "title": "Successful login with valid credentials",
      "steps": [
        { "keyword": "Given", "text": "the user is on the login page" },
        { "keyword": "And", "text": "a registered account exists with email \"sarah.martin@devoteam.com\" and password \"Str0ngP@ss!2026\"" },
        { "keyword": "When", "text": "the user enters email \"sarah.martin@devoteam.com\"" },
        { "keyword": "And", "text": "the user enters password \"Str0ngP@ss!2026\"" },
        { "keyword": "And", "text": "the user clicks the \"Sign In\" button" },
        { "keyword": "Then", "text": "the user is redirected to the personalized dashboard" },
        { "keyword": "And", "text": "the dashboard displays \"Welcome, Sarah\"" }
      ]
    },
    {
      "tags": ["@negative", "@authentication"],
      "type": "Scenario",
      "title": "Login fails with incorrect password",
      "steps": [
        { "keyword": "Given", "text": "the user is on the login page" },
        { "keyword": "And", "text": "a registered account exists with email \"sarah.martin@devoteam.com\"" },
        { "keyword": "When", "text": "the user enters email \"sarah.martin@devoteam.com\"" },
        { "keyword": "And", "text": "the user enters password \"WrongPassword99\"" },
        { "keyword": "And", "text": "the user clicks the \"Sign In\" button" },
        { "keyword": "Then", "text": "an error message \"Invalid email or password\" is displayed" },
        { "keyword": "And", "text": "the user remains on the login page" }
      ]
    },
    {
      "tags": ["@negative", "@validation"],
      "type": "Scenario Outline",
      "title": "Login fails with empty required fields",
      "steps": [
        { "keyword": "Given", "text": "the user is on the login page" },
        { "keyword": "When", "text": "the user enters email \"<email>\"" },
        { "keyword": "And", "text": "the user enters password \"<password>\"" },
        { "keyword": "And", "text": "the user clicks the \"Sign In\" button" },
        { "keyword": "Then", "text": "the validation error \"<error_message>\" is displayed" }
      ],
      "examples": {
        "headers": ["email", "password", "error_message"],
        "rows": [
          ["", "Str0ngP@ss!2026", "Email is required"],
          ["sarah.martin@devoteam.com", "", "Password is required"],
          ["", "", "Email is required"]
        ]
      }
    },
    {
      "tags": ["@security", "@edge-case"],
      "type": "Scenario",
      "title": "Account is locked after 5 consecutive failed login attempts",
      "steps": [
        { "keyword": "Given", "text": "the user is on the login page" },
        { "keyword": "And", "text": "a registered account exists with email \"sarah.martin@devoteam.com\"" },
        { "keyword": "And", "text": "the account has 4 previous failed login attempts" },
        { "keyword": "When", "text": "the user enters email \"sarah.martin@devoteam.com\"" },
        { "keyword": "And", "text": "the user enters an incorrect password" },
        { "keyword": "And", "text": "the user clicks the \"Sign In\" button" },
        { "keyword": "Then", "text": "the account is locked" },
        { "keyword": "And", "text": "the message \"Your account has been locked due to multiple failed attempts. Please try again later.\" is displayed" }
      ]
    }
  ]
}

{
  "feature_title": "Shopping Cart Management",
  "feature_description": "Enables customers to add, manage and review items in their shopping cart before purchase",
  "scenarios": [
    {
      "tags": ["@smoke", "@cart"],
      "type": "Scenario",
      "title": "Successfully add a product to an empty cart",
      "steps": [
        { "keyword": "Given", "text": "the user is viewing the product page for \"MacBook Pro 16-inch\" priced at \"2499.00 EUR\"" },
        { "keyword": "And", "text": "the shopping cart is empty" },
        { "keyword": "When", "text": "the user clicks the \"Add to Cart\" button" },
        { "keyword": "Then", "text": "the product \"MacBook Pro 16-inch\" is added to the cart" },
        { "keyword": "And", "text": "the cart counter displays \"1\"" },
        { "keyword": "And", "text": "a confirmation toast \"Item added to your cart\" is shown" }
      ]
    },
    {
      "tags": ["@regression", "@cart"],
      "type": "Scenario",
      "title": "Adding an existing product increments its quantity",
      "steps": [
        { "keyword": "Given", "text": "the user has 1 unit of \"MacBook Pro 16-inch\" in the cart" },
        { "keyword": "When", "text": "the user visits the product page for \"MacBook Pro 16-inch\"" },
        { "keyword": "And", "text": "the user clicks the \"Add to Cart\" button" },
        { "keyword": "Then", "text": "the cart shows quantity \"2\" for \"MacBook Pro 16-inch\"" },
        { "keyword": "And", "text": "the cart counter displays \"2\"" }
      ]
    },
    {
      "tags": ["@regression", "@cart"],
      "type": "Scenario",
      "title": "Cart total reflects accurate price calculation",
      "steps": [
        { "keyword": "Given", "text": "the user has the following items in the cart:" },
        { "keyword": "And", "text": "1x \"MacBook Pro 16-inch\" at \"2499.00 EUR\"" },
        { "keyword": "And", "text": "2x \"USB-C Hub\" at \"49.99 EUR\"" },
        { "keyword": "When", "text": "the user views the cart summary" },
        { "keyword": "Then", "text": "the subtotal displays \"2598.98 EUR\"" },
        { "keyword": "And", "text": "the total accurately reflects the sum of all item prices multiplied by their quantities" }
      ]
    }
  ]
}
